use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let _work = 1;
    drop(permit);
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let _work = 2;
    drop(permit);
}

fn main() {
    let s = Semaphore::new(1);
    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let t1 = thread::spawn(move || w1(s1));
    let t2 = thread::spawn(move || w2(s2));

    t1.join().unwrap();
    t2.join().unwrap();

